import{_ as s,C as o,o as n,c as l,j as t,a as i,G as d,a3 as r}from"./chunks/framework.B6x8LOwa.js";const y=JSON.parse('{"title":"贡献流程","description":"分支策略、提交规范、PR 检查与代码规范","frontmatter":{"title":"贡献流程","description":"分支策略、提交规范、PR 检查与代码规范"},"headers":[],"relativePath":"cn/dev/getting-started/contributing.md","filePath":"cn/dev/getting-started/contributing.md"}'),p={name:"cn/dev/getting-started/contributing.md"};function g(h,e,u,m,b,k){const a=o("ArticleMetadata"),c=o("HelpUsImprove");return n(),l("div",null,[e[0]||(e[0]=t("h1",{id:"贡献流程",tabindex:"-1"},[i("贡献流程 "),t("a",{class:"header-anchor",href:"#贡献流程","aria-label":'Permalink to "贡献流程"'},"​")],-1)),d(a),d(c),e[1]||(e[1]=r(`<p>主开发分支是 <code>net6</code>。<code>main</code> 是历史遗留分支，实际上已不活跃。所有 PR 都应提交到 <code>net6</code>。</p><h2 id="分支策略" tabindex="-1">分支策略 <a class="header-anchor" href="#分支策略" aria-label="Permalink to &quot;分支策略&quot;">​</a></h2><p>只有一个活跃开发分支：<strong><code>net6</code></strong>。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net6 (主开发分支)</span></span>
<span class="line"><span>  ├─ feature/xxx (功能分支)</span></span>
<span class="line"><span>  ├─ fix/yyy (修复分支)</span></span>
<span class="line"><span>  └─ PR → net6</span></span></code></pre></div><p><code>sync-net6-to-net10.yml</code> 会在 <code>net6</code> 有新提交时自动把改动合并到 <code>net10</code> 分支（.NET 10 迁移分支），细节见文末。</p><div class="warning custom-block"><p class="custom-block-title">不要直接推送到 main</p><p>虽然 <code>prcheck.yml</code> 允许 PR 到 <code>main</code>，但实际开发都在 <code>net6</code>。除非维护者明确要求，否则不要向 <code>main</code> 提交。</p></div><h2 id="提交信息规范" tabindex="-1">提交信息规范 <a class="header-anchor" href="#提交信息规范" aria-label="Permalink to &quot;提交信息规范&quot;">​</a></h2><p>项目使用 <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> 规范，<code>git-cliff</code> 根据提交信息自动生成 Changelog。</p><h3 id="前缀到-changelog-分组的映射" tabindex="-1">前缀到 Changelog 分组的映射 <a class="header-anchor" href="#前缀到-changelog-分组的映射" aria-label="Permalink to &quot;前缀到 Changelog 分组的映射&quot;">​</a></h3><p><code>build/cliff.toml</code> 的 <code>commit_parsers</code> 决定了提交落到哪个分组。<strong>中文前缀同样被识别</strong>，这是这套配置和标准 Conventional Commits 最大的区别：</p><table tabindex="0"><thead><tr><th>提交信息前缀</th><th>Changelog 分组</th></tr></thead><tbody><tr><td><code>feat</code> / <code>add</code> / <code>新增</code> / <code>添加</code></td><td>🚀 新增功能</td></tr><tr><td><code>fix</code> / <code>修复</code></td><td>🐛 修复</td></tr><tr><td><code>refactor</code></td><td>🚜 重构</td></tr><tr><td><code>improve</code> / <code>改进</code> / <code>优化</code></td><td>⚡ 体验优化</td></tr><tr><td><code>delete</code> / <code>删除</code> / <code>移除</code></td><td>❌ 删除功能</td></tr><tr><td><code>doc</code></td><td>📚 文档更改</td></tr><tr><td><code>style</code></td><td>🎨 格式化</td></tr><tr><td><code>test</code></td><td>🧪 测试</td></tr><tr><td><code>chore</code> / <code>ci</code></td><td>⚙️ 杂项</td></tr><tr><td><code>Revert</code></td><td>◀️ 回退</td></tr><tr><td><code>版本</code> / <code>version</code> / <code>更新版本号</code></td><td>🎉 版本号更新</td></tr><tr><td>其他任何内容</td><td>💼 其他更改</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">没有任何提交会被丢弃</p><p><code>filter_commits = false</code> 且最后一条规则是 <code>{ message = &quot;.*&quot;, group = &quot;其他更改&quot; }</code>。写得再随意的提交信息也会进 Changelog，只是落到「💼 其他更改」里。想让 Changelog 好看，就老老实实写前缀。</p></div><p>以下几类会被显式跳过（<code>skip = true</code>），不出现在 Changelog：</p><ul><li><code>chore(release): prepare for ...</code></li><li><code>chore(deps...)</code> —— Dependabot 的依赖更新</li><li><code>chore(pr)</code> / <code>chore(pull)</code></li><li><code>Merge branch ...</code></li></ul><div class="tip custom-block"><p class="custom-block-title">典型提交示例</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feat(plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): 支持插件注册全局快捷键</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">在</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IPluginHost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 添加</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RegisterHotkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 方法，允许插件在</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Initialize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 阶段注册全局快捷键。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Closes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #1234</span></span></code></pre></div><p>提交信息里写 <code>#1234</code> 会被 <code>link_parsers</code> 自动转成指向 community 仓库 issue 的链接。</p></div><h2 id="pr-检查门禁" tabindex="-1">PR 检查门禁 <a class="header-anchor" href="#pr-检查门禁" aria-label="Permalink to &quot;PR 检查门禁&quot;">​</a></h2><p>提交 PR 到 <code>net6</code> 或 <code>main</code> 后会触发以下检查：</p><h3 id="_1-prcheck-yml-——-构建与打包" tabindex="-1">1. prcheck.yml —— 构建与打包 <a class="header-anchor" href="#_1-prcheck-yml-——-构建与打包" aria-label="Permalink to &quot;1. prcheck.yml —— 构建与打包&quot;">​</a></h3><p><strong>触发条件</strong>：PR opened/synchronize，<code>paths-ignore: [&quot;**/*.md&quot;]</code>（纯 Markdown 改动不跑）。</p><p><strong>矩阵</strong>：<code>AnyCPU</code> 和 <code>x86</code> 两个架构并行构建。</p><p><strong>关键检查</strong>：</p><ul><li><code>dotnet restore --locked-mode</code> —— <code>PackageReference</code> 变更必须同步提交 <code>packages.lock.json</code>，否则失败</li><li>构建 <code>Debug</code> 配置 + <code>/p:RunAnalyzers=false</code>（不跑代码分析器，加快速度）</li><li>检查 VSTO DLL 是否生成（<code>Microsoft.Office.Tools.Common.v4.0.Utilities.dll</code> 必须存在）</li><li>检查主程序 exe 是否生成</li><li>打包产物并上传 artifact</li></ul><p>证书相关：有 <code>CERT_PFX_BASE64</code> secret 则导入真实证书，否则自动生成自签证书。Fork 的 PR 也能过（会用自签）。</p><h3 id="_2-linter-yml-——-代码检查" tabindex="-1">2. linter.yml —— 代码检查 <a class="header-anchor" href="#_2-linter-yml-——-代码检查" aria-label="Permalink to &quot;2. linter.yml —— 代码检查&quot;">​</a></h3><p><strong>触发条件</strong>：push/PR 到 <code>net6</code>，同样忽略 Markdown。</p><p><strong>Linter</strong>：<code>super-linter v8.6.0</code>，但 <code>DISABLE_ERRORS: true</code>（<strong>只报告，不阻断 PR</strong>）。</p><p><strong>关闭的检查</strong>：<code>VALIDATE_BIOME_FORMAT</code>、<code>VALIDATE_SPELL_CODESPELL</code>、<code>VALIDATE_GITLEAKS</code>（不检查密钥泄露，因为有测试用自签证书）。</p><div class="tip custom-block"><p class="custom-block-title">Linter 不会让 PR 失败</p><p>即使有格式问题，<code>linter.yml</code> 也只会在 Summary 里报告，不会阻断合并。但还是建议修复，保持代码质量。</p></div><h2 id="代码规范" tabindex="-1">代码规范 <a class="header-anchor" href="#代码规范" aria-label="Permalink to &quot;代码规范&quot;">​</a></h2><p>完整规范在 <code>community/rules/</code> 目录，这里列出最容易踩的几条。</p><h3 id="通用规范-general-md" tabindex="-1">通用规范（general.md） <a class="header-anchor" href="#通用规范-general-md" aria-label="Permalink to &quot;通用规范（general.md）&quot;">​</a></h3><ol><li><strong>所有用户可见文本必须走 i18n</strong>。不要在 XAML 或代码中直接写死中文/英文。用 <code>Strings.GetString(&quot;KeyName&quot;)</code>。</li><li><strong><code>Geometry.Parse()</code> 结果是只读的</strong>。修改前必须先 <code>Clone()</code>，否则抛异常。</li><li><strong>不要在 <code>AfterBuild</code> 事件里操作视觉树</strong>。异常会被 try-catch 吞掉，你看不到报错。要操作视觉树就延迟到 <code>Loaded</code> 事件。</li><li><strong><code>Thickness</code> 禁用双参构造函数</strong>。WPF for .NET 6 不支持 <code>Thickness(double, double)</code>，必须用四参数 <code>Thickness(left, top, right, bottom)</code>。</li><li><strong>私有字段用 <code>_</code> 前缀</strong>，如 <code>_stylusDownTimestamp</code>。XAML 控件名用 PascalCase，如 <code>CardEnableInkFade</code>。</li><li><strong>IsHighlighter 的语义</strong>：普通笔/激光笔恒为 <code>false</code>，荧光笔为 <code>!Settings.Canvas.HighlighterOverlapEnabled</code>（覆盖模式时为 false，透明模式时为 true）。</li></ol><h3 id="xaml-控件规范-xaml-controls-md" tabindex="-1">XAML 控件规范（xaml_controls.md） <a class="header-anchor" href="#xaml-控件规范-xaml-controls-md" aria-label="Permalink to &quot;XAML 控件规范（xaml_controls.md）&quot;">​</a></h3><ol><li><strong>所有 <code>&lt;ComboBox&gt;</code> 不得设置 <code>Width</code>、<code>MinWidth</code> 或 <code>MaxWidth</code></strong>。应当删除这些属性，让 ComboBox 自适应。</li><li><strong>带开关的设置项必须用 <code>LabeledSettingsCard</code></strong>，不要手动在 <code>ui:SettingsCard</code> 里嵌套 <code>ui:ToggleSwitch</code>。</li><li><strong><code>Expander.Items</code> 内禁用 <code>LabeledSettingsCard</code></strong>。Expander 里只能用 <code>ui:SettingsCard</code>（会产生视觉嵌套问题）。</li><li><strong><code>&lt;SymbolIcon&gt;</code> 必须显式设置 <code>FontSize</code></strong>，否则在某些 DPI 下会异常放大。</li><li><strong><code>&lt;ComboBox&gt;</code> / <code>&lt;ComboBoxItem&gt;</code> 禁止设置 <code>Background</code></strong>。会覆盖主题样式，导致选中态错误。</li></ol><h3 id="设置页规范-settings-pages-md" tabindex="-1">设置页规范（settings_pages.md） <a class="header-anchor" href="#设置页规范-settings-pages-md" aria-label="Permalink to &quot;设置页规范（settings_pages.md）&quot;">​</a></h3><p>这是最长的规范文档（378 行），核心要求：</p><ol><li><strong>设置项必须有 <code>Header</code> 和 <code>Description</code></strong>。<code>Header</code> 用 i18n 字符串，<code>Description</code> 解释清楚这个选项的作用与影响。</li><li><strong>切换开关放在卡片右侧</strong>，用 <code>&lt;LabeledSettingsCard&gt;</code>。</li><li><strong>复杂设置用 <code>Expander</code> 分组</strong>，把高级选项收起来。</li><li><strong>设置变更必须通过 <code>SettingsActionHub</code> 调用主窗口方法</strong>，而不是直接操作 <code>MainWindow</code> 字段。</li><li><strong>设置保存是自动的</strong>。<code>SettingsManager</code> 会在属性变更后自动调用 <code>SaveSettingsToFile()</code>，你不需要显式保存。</li></ol><h3 id="工具栏规范-toolbar-md" tabindex="-1">工具栏规范（toolbar.md） <a class="header-anchor" href="#工具栏规范-toolbar-md" aria-label="Permalink to &quot;工具栏规范（toolbar.md）&quot;">​</a></h3><ol><li><strong>浮动工具栏（FloatingToolbar）与白板工具栏（BoardToolbar）是两套独立体系</strong>，没有共享接口。</li><li><strong>工具栏项通过反射自动发现</strong>。实现 <code>IToolbarItem</code>，有公共无参构造函数，就会被 <code>ToolbarRegistry.Discover()</code> 找到。</li><li><strong>插件工具栏项通过 <code>RegisterToolbarItem()</code> 注册</strong>，会被包装成 <code>PluginToolbarItemWrapper</code> 适配到 <code>IToolbarItem</code>。</li><li><strong>工具栏布局保存在 <code>Configs/ToolbarConfigs/&lt;name&gt;.json</code></strong>，用 Newtonsoft.Json 序列化，有备份机制（<code>.json.bak</code>）。</li></ol><h3 id="popup-规范-popups-menus-md" tabindex="-1">Popup 规范（popups_menus.md） <a class="header-anchor" href="#popup-规范-popups-menus-md" aria-label="Permalink to &quot;Popup 规范（popups_menus.md）&quot;">​</a></h3><ol><li><strong>所有 <code>&lt;Popup&gt;</code> 必须注册到 <code>PopupManagerHelper</code></strong>，否则不会被 <code>CloseAllPopups()</code> 管理。</li><li><strong>Popup 内容用 <code>PopupShellContent</code> 或 <code>PopupTabShellContent</code></strong>。这两个控件提供统一的标题栏、关闭按钮、阴影效果。</li><li><strong><code>StaysOpen=&quot;true&quot;</code> + <code>Focusable=&quot;true&quot;</code></strong>。这样点击外部时 Popup 不会立即关闭（由 PopupManager 统一处理）。</li></ol><h2 id="测试要求" tabindex="-1">测试要求 <a class="header-anchor" href="#测试要求" aria-label="Permalink to &quot;测试要求&quot;">​</a></h2><p><code>CONTRIBUTING.md</code> 里明确了两类测试要求：</p><h3 id="人工编写代码" tabindex="-1">人工编写代码 <a class="header-anchor" href="#人工编写代码" aria-label="Permalink to &quot;人工编写代码&quot;">​</a></h3><ol><li><strong>简单的构建测试</strong> —— 避免提交不完整的代码。</li><li><strong>简单的运行测试</strong> —— UI 改动用「三步法」（一看样式，二看行为，三看 i18n 是否完整）；后端改动遵循「改什么测什么」。</li></ol><h3 id="ai-辅助代码" tabindex="-1">AI 辅助代码 <a class="header-anchor" href="#ai-辅助代码" aria-label="Permalink to &quot;AI 辅助代码&quot;">​</a></h3><ol><li><strong>进行 AI 辅助时必须理解每一行改动</strong>。</li><li><strong>进行全面的运行测试</strong> —— 包含所有可能受影响的局部，回归测试，针对性修复。</li><li><strong>严禁盲目使用 AI 进行修复</strong>。发现问题时必须仔细核对修改过程中的可疑 commit。</li></ol><div class="danger custom-block"><p class="custom-block-title">严重后果</p><p>CONTRIBUTING.md 第 22 行明确警告：「如果发现您存在不懂装懂的情况且拒不改正我们将您从贡献者中除名，并永久禁止您进行代码贡献。」</p></div><h2 id="其他工作流" tabindex="-1">其他工作流 <a class="header-anchor" href="#其他工作流" aria-label="Permalink to &quot;其他工作流&quot;">​</a></h2><h3 id="publish-sdk-nuget-yml" tabindex="-1">publish-sdk-nuget.yml <a class="header-anchor" href="#publish-sdk-nuget-yml" aria-label="Permalink to &quot;publish-sdk-nuget.yml&quot;">​</a></h3><p>把 <code>InkCanvas.PluginSdk</code> 和 <code>InkCanvas.Controls</code> 打包发布到 nuget.org。</p><p><strong>两种触发方式</strong>：</p><ul><li>push 形如 <code>sdk-v1.7.19.9</code> 的 tag —— 以 tag 里的版本号强制发包</li><li>手动 <code>workflow_dispatch</code> —— 可输入 <code>branch</code>（默认 <code>net6</code>）和 <code>version</code>；<code>version</code> 留空则用 NBGV 依据 git 状态算出的版本</li></ul><p>依赖仓库 Secret <code>NUGET_API_KEY</code>。并发组 <code>publish-sdk-nuget</code> 且 <code>cancel-in-progress: false</code>，避免两次发布互相打断。</p><h3 id="sync-net6-to-net10-yml" tabindex="-1">sync-net6-to-net10.yml <a class="header-anchor" href="#sync-net6-to-net10-yml" aria-label="Permalink to &quot;sync-net6-to-net10.yml&quot;">​</a></h3><p>push 到 <code>net6</code>（或手动触发）后，把 <code>net6</code> 合并进 <code>net10</code>。这个工作流做的事比「合并」多得多：</p><ol><li>合并 <code>net6</code> → <code>net10</code>，<strong>冲突自动解决</strong>：csproj 取 <code>net6</code> 版本，再把 TFM 改回 net10</li><li>删除旧的 <code>packages.lock.json</code></li><li>先尝试 <code>restore</code> + <code>build</code>（多数包同时支持 net6/net10，不用动）</li><li>构建失败才把所有 NuGet 包升到最新稳定版，重新 <code>restore</code> + <code>build</code></li><li><strong>只有编译通过才推送</strong>，否则中止并报警</li></ol><div class="tip custom-block"><p class="custom-block-title">不用管 net10 分支</p><p><code>net10</code> 是迁移分支，由这个工作流自动维护。日常开发只需要关心 <code>net6</code>，除非收到同步失败的告警。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./environment">环境搭建</a> — 安装 VS 2022、.NET 6 SDK、VSTO 工具</li><li><a href="./build-and-run">构建与运行</a> — 完整的构建、版本号、CI、打包流程</li><li><a href="./../core/conventions">代码规范汇总</a> — <code>community/rules/</code> 下所有规范的完整引用</li></ul>`,60))])}const P=s(p,[["render",g]]);export{y as __pageData,P as default};
